using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Reflection;
namespace DoomSNESed {
    public static class ConverterTests {
        static void Check(bool value,string message){Bin.Require(value,"Converter 0.4: "+message);}
        public static void Run(string path,string output){string resources=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"editor-data");var rom=new Rom(path,resources);var compat=new CompatibilityActions(resources);var messages=new List<string>();
            Check(compat.Line(109,true,false,messages.Add)==2,"fast walk-once open door maps to normal walk-once open door");Check(compat.Line(120,true,false,messages.Add)==88,"fast repeat lift retains walk-repeat activation");Check(compat.Line(100,true,false,messages.Add)==8,"fast 16 stairs maps to native 8 stairs");Check(compat.Line(124,true,false,messages.Add)==52,"secret walk exit maps to normal walk exit");Check(compat.Line(111,true,false,messages.Add)==29,"fast use-once door retains use-once activation");Check(compat.Line(138,true,false,messages.Add)==13,"unsupported switch light approximated with native light action");
            bool manual;Check(compat.Sector(17,true,false,out manual,messages.Add)==1&&!manual,"random flicker maps to random blink");Check(compat.Sector(14,true,false,out manual,messages.Add)==0&&manual,"timed door requests manual geometry preset");bool refused=false;try{compat.Line(65535,true,false,messages.Add);}catch(InvalidDataException){refused=true;}Check(refused,"unknown action is not guessed or silently deleted");refused=false;try{compat.Line(109,false,false,messages.Add);}catch(InvalidDataException){refused=true;}Check(refused,"strict action mode remains available");refused=false;try{compat.Line(138,true,false,messages.Add,false);}catch(InvalidDataException){refused=true;}Check(refused,"one-sided switch cannot silently become an unusable walk trigger");Check(messages.Count>=8,"replacement explanations recorded");
            Map simple=AdvancedTests.Empty(rom,0);AdvancedTests.Rect(simple,-256,-128,256,128,4);simple.Things.Add(new Thing{Type=0,Flags=0xef,X=0,Y=0});int line=simple.Walls.FindIndex(w=>simple.Vertices[w.Start].Y==128&&simple.Vertices[w.End].Y==128);GeometryTools.SplitWall(simple,line,new Point(0,128));simple.Vertices.Add(new Point(-256,-128));simple.Vertices.Add(new Point(500,500));int before=simple.Walls.Count;ConversionOptimizer.Apply(rom,simple,new ConversionOptions{MergeSectors=false},messages,delegate{});Check(simple.Walls.Count==before-1&&simple.Vertices.Count==4,"collinear textured walls collapse and unused vertices disappear");GeometryTools.Validate(simple);
            var cap=AdvancedTests.Empty(rom,0);AdvancedTests.Rect(cap,-512,-256,512,256,4);cap.Things.Add(new Thing{Type=0,Flags=0xef,X=0,Y=0});cap.Things.Add(new Thing{Type=6,Flags=0xef,X=64,Y=0});cap.Things.Add(new Thing{Type=6,Flags=0xef,X=128,Y=0});cap.Things.Add(new Thing{Type=12,Flags=0xef,X=256,Y=0});cap.Things.Add(new Thing{Type=50,Flags=0x87,X=128,Y=64});cap.Things.Add(new Thing{Type=21,Flags=0x87,X=-128,Y=0});cap.Sectors[0].Darkness=95;ConversionOptimizer.Apply(rom,cap,new ConversionOptions{MergeSectors=false,MonsterLimit=2,RemoveDecorations=true,LightingStep=32},messages,delegate{});Check(cap.Things.Count(t=>t.Type>=6&&t.Type<=14)==2&&cap.Things.Any(t=>t.Type==12)&&cap.Things.Any(t=>t.Type==21)&&!cap.Things.Any(t=>t.Type==50),"monster cap preserves Baron and key; scenery removal is separate");Check(cap.Sectors[0].Darkness==96,"lighting quantization follows chosen step");
            Map islands=AdvancedTests.Empty(rom,0);AdvancedTests.Rect(islands,-256,-128,0,128,4);AdvancedTests.Rect(islands,0,-128,256,128,4);AdvancedTests.Rect(islands,512,-128,768,128,4);byte[] rejection=NativeCompiler.Reject(islands);Check(rejection.Length==2&&rejection[0]==0xe4&&rejection[1]==0,"reject only disconnected sector pairs in native bit order");GeometryTools.Preset(islands,1,SectorMotion.Door);Check(NativeCompiler.Reject(islands).SequenceEqual(rejection),"closed door remains connected for conservative visibility");
            string fixture=Path.Combine(output,"converter-fixture.wad");var recommendations=ConversionRecommendations.Analyze(new Rom(path,resources),new WadFile(fixture),resources,null);Check(recommendations.Levels.SequenceEqual(new[]{"E1M1","E1M2"})&&recommendations.Options.MonsterLimit==0&&recommendations.Options.LightingStep==0&&!recommendations.Options.RemoveDecorations,"auto configure selects fitting levels and preserves ordinary gameplay settings");var incompatible=new WadFile(fixture);Bin.W16(incompatible.Map("E1M2")["LINEDEFS"],6,65535);var filtered=ConversionRecommendations.Analyze(new Rom(path,resources),incompatible,resources,null);Check(filtered.Levels.SequenceEqual(new[]{"E1M1"})&&filtered.Report.Contains("DISABLED E1M2"),"auto configure disables levels with untranslatable action logic");Check(Bin.Hex(Bin.Hash(rom.Bytes))==Rom.Identity,"recommendation analysis preserves the base ROM");
            var wad=new WadFile(fixture);var lumps=wad.Map("E1M1");Bin.W16(lumps["SECTORS"],24,600);Bin.W16(lumps["LINEDEFS"],6,13);Bin.W16(lumps["LINEDEFS"],8,600);var converter=new WadConverter(rom,resources);Map imported=converter.Import(wad,"E1M1",0,false);Check(imported.Sectors[0].Tag==1&&imported.Walls[0].Tag==1,"large PC tags compact and preserve links");
            var nativeRom=new Rom(path,resources);var native=new WadConverter(nativeRom,resources);var normal=new WadFile(fixture);byte[] image=native.Convert(normal,new[]{"E1M1"},true);nativeRom.SavePatch(Path.Combine(output,"native-campaign.dse"),image,true);Bin.Atomic(Path.Combine(output,"native-campaign.sfc"),image);Check(System.Text.Encoding.ASCII.GetString(File.ReadAllBytes(Path.Combine(output,"native-campaign.dse")),0,8)=="DSECNV2\0","native campaign sidecar has dedicated format");
            string project=Path.Combine(output,"native-campaign.sned");nativeRom.SaveProject(project);var reopened=new Rom(path,resources);reopened.LoadProject(project);Check(reopened.Project.CampaignSlots.SequenceEqual(nativeRom.Project.CampaignSlots)&&reopened.Compile().SequenceEqual(image),"campaign project reopens and recompiles byte-for-byte including routing");reopened.Project.Maps.First(m=>m.Slot==reopened.Project.CampaignSlots[0]).Sectors[0].Darkness=80;byte[] edited=reopened.Compile();Check(edited[0x1ffbc6]==27&&!edited.SequenceEqual(image),"editing a converted sector preserves final ending routing");reopened.SavePatch(Path.Combine(output,"native-edited.dse"),edited);Check(System.Text.Encoding.ASCII.GetString(File.ReadAllBytes(Path.Combine(output,"native-edited.dse")),0,8)=="DSECNV2\0","editor automatically saves campaign-format patches");Bin.Atomic(Path.Combine(output,"native-edited.sfc"),edited);
            foreach(bool sprite in new[]{false,true}){NativeGraphic asset=GraphicsAssets.Describe(nativeRom.Bytes,sprite,sprite?26:4);byte[] pixels=GraphicsAssets.Decode(nativeRom.Bytes,asset);Check(pixels.Length==asset.Width*asset.Height,"original graphic decodes");for(int y=0;y<asset.Height;y++)for(int x=0;x<asset.Width;x++)pixels[y*asset.Width+x]=(byte)(y<asset.Height/2?24:sprite?0:80);nativeRom.Project.Graphics.Add(new GraphicReplacement{Sprite=sprite,Id=asset.Id,Width=asset.Width,Height=asset.Height,Pixels=pixels});}
            foreach(Face face in nativeRom.Project.Maps.First(m=>m.Slot==nativeRom.Project.CampaignSlots[0]).Faces){face.Upper=4;face.Lower=4;}
            for(int id=0;id<232;id++){NativeGraphic frame=GraphicsAssets.Describe(nativeRom.Bytes,true,id);Check(GraphicsAssets.Decode(nativeRom.Bytes,frame).Length==frame.Width*frame.Height,"native sprite frame decodes "+id);}
            NativeGraphic sky=GraphicsAssets.Describe(nativeRom.Bytes,false,0);byte[] skyPixels=GraphicsAssets.Decode(nativeRom.Bytes,sky);for(int y=0;y<128;y++)for(int x=0;x<128;x++)skyPixels[y*128+x]=(byte)(y<64?24:80);nativeRom.Project.Graphics.Add(new GraphicReplacement{Id=0,Width=128,Height=128,Pixels=skyPixels});
            byte[] graphicsImage=nativeRom.Compile();foreach(var change in nativeRom.Project.Graphics)Check(GraphicsAssets.Decode(graphicsImage,GraphicsAssets.Describe(graphicsImage,change.Sprite,change.Id)).SequenceEqual(change.Pixels),"native graphics round-trip upright with transparent sprite pixels");nativeRom.SavePatch(Path.Combine(output,"native-graphics.dse"),graphicsImage);Bin.Atomic(Path.Combine(output,"native-graphics.sfc"),graphicsImage);nativeRom.SaveProject(Path.Combine(output,"native-graphics.sned"));var graphicProject=new Rom(path,resources);graphicProject.LoadProject(Path.Combine(output,"native-graphics.sned"));Check(graphicProject.Compile().SequenceEqual(graphicsImage),"graphics persist in editable project");Check(System.Text.Encoding.ASCII.GetString(File.ReadAllBytes(Path.Combine(output,"native-graphics.dse")),0,8)=="DSEGFX3\0","native graphics patch profile");
            using(var wrong=new Bitmap(1,1)){string wrongPath=Path.Combine(output,"wrong-size.png");wrong.Save(wrongPath);refused=false;try{GraphicsAssets.Import(nativeRom,GraphicsAssets.Describe(nativeRom.Bytes,false,4),wrongPath);}catch(InvalidDataException){refused=true;}Check(refused,"mismatched graphic dimensions rejected");}
            foreach(int screen in new[]{1,2}){using(var original=ScreenAssets.Original(nativeRom,screen)){Check(original.Width==256&&original.Height==224,"original compressed screen decodes");original.Save(Path.Combine(output,"original-screen-"+screen+".png"));}using(var artwork=new Bitmap(256,224)){using(Graphics g=Graphics.FromImage(artwork)){g.Clear(Color.Black);g.FillRectangle(Brushes.Lime,0,0,128,112);g.FillRectangle(Brushes.Red,128,112,128,112);}string png=Path.Combine(output,"screen-import.png");artwork.Save(png);nativeRom.Project.Graphics.Add(ScreenAssets.Import(new NativeGraphic{Screen=screen},png));}}
            byte[] screens=nativeRom.Compile();nativeRom.SavePatch(Path.Combine(output,"native-screens.dse"),screens);Bin.Atomic(Path.Combine(output,"native-screens.sfc"),screens);nativeRom.SaveProject(Path.Combine(output,"native-screens.sned"));Check(Bin.U16(screens,0xeff89)==8&&Bin.U16(screens,0x1ff03d)==8,"compressible screens use native compressed VRAM transfers");Check(Bin.Hex(Bin.Hash(nativeRom.Bytes))==Rom.Identity,"graphics import preserves original ROM");
            var overflowing=new Rom(path,resources);overflowing.LoadProject(Path.Combine(output,"native-campaign.sned"));overflowing.Project.CampaignSlots=null;var noise=new GraphicReplacement{Id=4,Width=128,Height=128,Pixels=new byte[128*128]};for(int y=0;y<128;y++)for(int x=0;x<128;x++)noise.Pixels[y*128+x]=(byte)(x*13+y*7);overflowing.Project.Graphics.Add(noise);for(int i=0;i<400;i++){var sprite=GraphicsAssets.Describe(overflowing.Bytes,true,i%232);var randomPixels=new byte[sprite.Width*sprite.Height];new Random(i+100).NextBytes(randomPixels);overflowing.Project.Graphics.Add(new GraphicReplacement{Sprite=true,Id=i%232,Width=sprite.Width,Height=sprite.Height,Pixels=randomPixels});}refused=false;try{overflowing.Compile();}catch(InvalidDataException ex){refused=ex.Message.Contains("do not fit");}Check(refused,"graphics overflow is rejected before exporting a ROM");
            // Native walk exit fixture exercises the actual crossing action in the game.
            var walking=new WadFile(fixture);var walkLumps=walking.Map("E1M1");byte[] lines=walkLumps["LINEDEFS"];bool changed=false;for(int i=0;i<lines.Length;i+=14)if(Bin.U16(lines,i+12)!=65535){Bin.W16(lines,i+6,124);changed=true;break;}Check(changed,"walk exit placed on the inter-room portal");var walkRom=new Rom(path,resources);byte[] walkImage=new WadConverter(walkRom,resources).Convert(walking,new[]{"E1M1"},true);walkRom.SavePatch(Path.Combine(output,"walk-campaign.dse"),walkImage,true);Bin.Atomic(Path.Combine(output,"walk-campaign.sfc"),walkImage);
            var timed=new WadFile(fixture);Bin.W16(timed.Map("E1M1")["SECTORS"],26+22,14);var timedMap=new WadConverter(rom,resources).Import(timed,"E1M1",0,false);Check(timedMap.Sectors[1].Motion==SectorMotion.Door&&timedMap.Sectors[1].Ceiling==timedMap.Sectors[1].Floor&&timedMap.Walls.Any(w=>w.Type==1),"timed sector becomes a working manual door");
            byte[] exe=File.ReadAllBytes(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"DoomSNESconv.exe"));Check(exe.Length>300000,"converter contains embedded icon resources");using(var icon=Icon.ExtractAssociatedIcon(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"DoomSNESconv.exe")))Check(icon!=null&&icon.Width>=16,"converter native icon loads without PNG dependency");
            File.WriteAllText(Path.Combine(output,"converter-04-results.txt"),"PASS: auto configure selects fitting levels / excludes missing action logic without source writes; action replacements and strict rejection; timed-sector doors; tag compaction; texture-safe wall collapse; vertex cleanup; conservative native visibility rejection; lighting quantization; per-skill monster limits / boss-key preservation; scenery option; native campaign sidecars; editable campaign round-trip / routing preservation; embedded converter icon.\r\n");
        }
    }
}

